"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Elke kamer: duurzaamheid burcht +{0}%. Past bij “Verdediging”: kleiwachters ×{1} verdedigen mee.",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Elke kamer: relikwieën op expedities +{0}. Past bij “Verdediging”: wapens: schade +{1}%, spatschade en vertraging bij treffer; overige: wachters +{2}.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Elke kamer: meegebrachte voorraden +{0}%. Past bij “Geluk”: voorraden nog eens +{1}%, start-puntenvermenigvuldiger +{2} per gevecht.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Elke kamer: expeditiezicht +{0}, start-puntenvermenigvuldiger +{1}. Past bij “Geluk / Speciaal”: expeditiekaart vanaf het begin zichtbaar, vermenigvuldiger nog eens +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Elke kamer: aanval expeditietroepen +{0}%. Past bij “Training”: expeditie-XP leider +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Elke kamer: HP expeditietroepen +{0}%. Past bij “Medisch”: ziekenhuisgenezing +{1}%, leider geneest dagelijks nog {2}%.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Elke kamer: dropkans bouwtekeningen +{0}%. Past bij “Sci-fi”: basis +{1} zielsscherven per dag.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Elke kamer: dropkans bouwtekeningen +{0}%. Past bij “Smeden”: {1}% kans op een extra relikwie bij het smeden.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Elke kamer: basis +{0} zielsscherven per dag. Past bij “Magie”: nog eens +{1} per dag.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Elke kamer: basis +{0} voorraden per dag. Past bij “Logistiek”: eigen effect van deze kamer ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Elke kamer: basis +{0} voorraden per dag, leider krijgt {1} XP per dag. Past bij “Logistiek / Natuur”: eigen effect van deze kamer ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Elke kamer: smeedkosten relikwieën -{0}%. Past bij “Smeden / Wapen”: smeden: {1}% kans op kwaliteit +{2}; wapens: schade +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Elke kamer: bouwtijd gehalveerd, {0}% van de voorraden terug bij voltooiing. Past bij “Wereldwonder”: terugbetaling stijgt naar {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Elke kamer: schade van alle verdedigingstorens +{0}%. Past bij “Wapen”: bereik +{1}, aanvalssnelheid +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Elke kamer: graafkosten -{0}%. Past bij “Speciaal”: alle bouw duurt {1} d korter.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Elke kamer: start-puntenvermenigvuldiger +{0} per gevecht. Past bij “Smeden”: gesmede relikwieën altijd kwaliteit +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Elke kamer: afkoeling leidervaardigheid -{0} halte(s). Past bij “Geluk”: hulpmiddelen bij expeditiestart +{1} (effecten minstens “Episch”).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Elke kamer: leideraanval +{0}%. Past bij “Wapen”: schade +{1}%, elke aanval ontketent kettingbliksem ({2} sprongen).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Elke kamer: je leider geneest {0}% HP per dag (zonder ziekenhuis). Past bij “Medisch / Water”: ziekenhuisgenezing +{1}%; bereik waterwapens +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Elke kamer: je leider krijgt {0} XP per dag. Past bij “Productie”: eigen opbrengst van deze kamer ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Elke kamer: je leider krijgt {0} XP per dag. Past bij “Training”: expeditie-XP leider +{1}%.",
