"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Vooruit: “Kerkhof”. Daar is de mist het dichtst, en elke nacht komen er verse graven bij.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Vooruit: “Assemblagehal”. Het laatste wat de fabriek bouwde, sloot alle arbeiders in zich op.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Vooruit: “Operatiekamer”. De directeur zegt dat de operatie geslaagd is – de patiënt is alleen nog niet wakker.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Vooruit: “Zeebodem”. Onder de haven ligt nog een stad, en haar poort is een muil.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Vooruit: “Boom der Kennis”. Hij herinnert zich alles wat ooit in het woud gebeurde en wil zich niets meer herinneren.",
